-- Review before applying to the gateway LOG database. Not an automatic migration.
CREATE TABLE `native_tasks` (`recovery_owner` varchar(64),`recovery_until` bigint,`next_recovery_at` bigint,`billing_settled` boolean,`delivery_base` varchar(512),`artifact_manifest` longtext,`delivered_output` longtext,`billing_receipt_json` longtext,`frozen_contract` longtext,`native_input` longtext,`channel_id` bigint,`endpoint` varchar(256),`key_fingerprint` varchar(64),`credential_scope` varchar(128),`prepayment_quote_json` longtext,`billing_operation_id` varchar(200),`error_code` varchar(64),`upstream_id` varchar(256),`id` varchar(128),`group_id` varchar(64) NOT NULL,`token_id` bigint NOT NULL,`model` varchar(256) NOT NULL,`fingerprint` varchar(64) NOT NULL,`output_schema` longtext NOT NULL,`output_schema_hash` varchar(64) NOT NULL,`status` varchar(32) NOT NULL,`native_output` longtext,`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,PRIMARY KEY (`id`),INDEX `idx_native_tasks_recovery_until` (`recovery_until`),INDEX `idx_native_tasks_next_recovery_at` (`next_recovery_at`),INDEX `idx_native_tasks_billing_settled` (`billing_settled`),INDEX `idx_native_tasks_group_id` (`group_id`));
